const svg=$('#model-svg'), out=$('#model-out');
const accSl=$('#model-acc'), accL=$('#model-acc-lbl');
const bL=$('#model-listen'), bOL=$('#model-openL'), bOR=$('#model-openR');
const W=640,H=300;
// hidden true state: 0 = tiger-left (TL), 1 = tiger-right (TR). Fixed at TL for the demo.
const trueState=0;
let lastAction=null, lastObs=null;
function render(){
  const acc=+accSl.value; accL.textContent='Z(hear-left | TL) = '+acc.toFixed(2);
  svg.innerHTML='';
  // two doors
  const doorY=70, doorW=150, doorH=140;
  const dx=[110, 380];
  for(let d=0;d<2;d++){
    const isTiger = (trueState===d);
    svg.appendChild(SVG('rect',{x:dx[d],y:doorY,width:doorW,height:doorH,rx:8,fill:'var(--panel2)',stroke: isTiger?'var(--pink)':'var(--green)','stroke-width':2}));
    const lbl=SVG('text',{x:dx[d]+doorW/2,y:doorY-12,'text-anchor':'middle','font-size':13,fill:'var(--mute)'}); lbl.textContent=(d===0?'LEFT door':'RIGHT door'); svg.appendChild(lbl);
    const inside=SVG('text',{x:dx[d]+doorW/2,y:doorY+doorH/2+5,'text-anchor':'middle','font-size':15,fill: isTiger?'var(--pink)':'var(--green)','font-weight':600});
    inside.textContent = isTiger?'TIGER (hidden)':'(safe, hidden)'; svg.appendChild(inside);
  }
  // observation banner
  const banY=250;
  const obsTxt=SVG('text',{x:W/2,y:banY,'text-anchor':'middle','font-size':14,fill:'var(--yellow)','font-weight':600});
  if(lastAction==='listen') obsTxt.textContent='you heard: '+(lastObs===0?'a growl on the LEFT':'a growl on the RIGHT');
  else if(lastAction) obsTxt.textContent='you opened a door — no informative observation';
  else obsTxt.textContent='choose an action below';
  svg.appendChild(obsTxt);
  // lines
  const rows=[];
  rows.push('hidden true state: tiger-LEFT (the agent never sees this)');
  if(lastAction==='listen'){
    const pHearLeft = (trueState===0)? acc : (1-acc);
    rows.push('action: listen   →   observation o = hear-'+(lastObs===0?'left':'right'));
    rows.push('Z(hear-left | TL, listen) = '+acc.toFixed(2)+'    Z(hear-right | TL, listen) = '+(1-acc).toFixed(2));
    rows.push('listening leaves the state unchanged (T = Id) but the growl is noisy — it is right '+(acc*100).toFixed(0)+'% of the time');
  } else if(lastAction==='open-left' || lastAction==='open-right'){
    const opened = lastAction==='open-left'?0:1;
    const safe = (opened!==trueState);
    rows.push('action: '+lastAction+'   →   '+(safe?'no tiger behind that door (reward)':'the tiger was there (big penalty)'));
    rows.push('opening yields no informative observation: Z(o | s\', open) is uninformative — the gamble resolves the episode.');
  } else {
    rows.push('press “listen” to sample a noisy observation, or open a door to gamble.');
  }
  out.textContent = rows.join('\n');
}
function sampleListen(){ const acc=+accSl.value; const pHearLeft=(trueState===0)?acc:(1-acc); lastAction='listen'; lastObs=(Math.random()<pHearLeft)?0:1; render(); }
bL.addEventListener('click',sampleListen);
bOL.addEventListener('click',()=>{ lastAction='open-left'; lastObs=null; render(); });
bOR.addEventListener('click',()=>{ lastAction='open-right'; lastObs=null; render(); });
accSl.addEventListener('input',render);
render();

const svg=$('#belief-svg'), out=$('#belief-out');
const accSl=$('#belief-acc'), accL=$('#belief-acc-lbl');
const hL=$('#belief-hL'), hR=$('#belief-hR'), rs=$('#belief-reset');
const W=640,H=220, padL=60, padR=60, axY=110;
let b=0.5, hist=[];
function update(obsLeft){
  const acc=+accSl.value;
  // listen: T = Id, so predict leaves b unchanged. Correct by Z, then normalize.
  // Z(hear-left | TL)=acc, Z(hear-left | TR)=1-acc.
  const zL = obsLeft? acc : (1-acc);      // Z(o | TL)
  const zR = obsLeft? (1-acc) : acc;      // Z(o | TR)
  const num = zL*b, den = zL*b + zR*(1-b);
  b = num/den;
  hist.push(obsLeft?'L':'R');
}
function render(){
  const acc=+accSl.value; accL.textContent='accuracy = '+acc.toFixed(2);
  svg.innerHTML='';
  const x0=padL, x1=W-padR;
  // the belief segment [0,1]
  svg.appendChild(SVG('line',{x1:x0,y1:axY,x2:x1,y2:axY,stroke:'var(--line)','stroke-width':2}));
  // ticks at 0,0.5,1
  [[0,'b=0  (certain TR)'],[0.5,'0.5'],[1,'b=1  (certain TL)']].forEach(([t,lab])=>{
    const x=x0+(x1-x0)*t;
    svg.appendChild(SVG('line',{x1:x,y1:axY-6,x2:x,y2:axY+6,stroke:'var(--mute)','stroke-width':1}));
    const tx=SVG('text',{x:x,y:axY+26,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); tx.textContent=lab; svg.appendChild(tx);
  });
  const bx=x0+(x1-x0)*b;
  svg.appendChild(SVG('circle',{cx:bx,cy:axY,r:8,fill:'var(--yellow)',stroke:'var(--bg)','stroke-width':2}));
  const bl=SVG('text',{x:bx,y:axY-16,'text-anchor':'middle','font-size':13,fill:'var(--yellow)','font-weight':600}); bl.textContent='b(TL) = '+b.toFixed(3); svg.appendChild(bl);
  const ttl=SVG('text',{x:W/2,y:34,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); ttl.textContent='belief = a point on the 1-D simplex (the segment [0,1])'; svg.appendChild(ttl);
  out.textContent =
    'belief b(TL) = '+b.toFixed(4)+'    b(TR) = '+(1-b).toFixed(4)+'    (sums to 1 — a distribution over the two hidden states)\n'+
    'growls heard so far: '+(hist.length? hist.join(' ') : '(none yet)')+'\n'+
    'each listen: predict (T=Id, b unchanged) → correct by Z(o|·) → renormalize.  More agreeing growls ⇒ belief → certainty; a contrary growl pulls it back.\n'+
    'b is a sufficient statistic: it summarizes the entire history, so the agent can act on b alone.';
}
hL.addEventListener('click',()=>{ update(true); render(); });
hR.addEventListener('click',()=>{ update(false); render(); });
rs.addEventListener('click',()=>{ b=0.5; hist=[]; render(); });
accSl.addEventListener('input',render);
render();

const svg=$('#bmdp-svg'), out=$('#bmdp-out');
const bSl=$('#bmdp-b'), bL=$('#bmdp-b-lbl'), accSl=$('#bmdp-acc'), accL=$('#bmdp-acc-lbl');
const listenBtn=$('#bmdp-listen'), openBtn=$('#bmdp-open');
const W=640,H=260, padL=60, padR=60, topY=70, botY=200;
let mode='listen';
function bayes(b,acc,obsLeft){ const zL=obsLeft?acc:(1-acc), zR=obsLeft?(1-acc):acc; return (zL*b)/(zL*b+zR*(1-b)); }
function xOf(t){ return padL+(W-padL-padR)*t; }
function drawAxis(y,label){
  svg.appendChild(SVG('line',{x1:padL,y1:y,x2:W-padR,y2:y,stroke:'var(--line)','stroke-width':2}));
  [0,0.5,1].forEach(t=>{ const x=xOf(t); svg.appendChild(SVG('line',{x1:x,y1:y-5,x2:x,y2:y+5,stroke:'var(--mute)','stroke-width':1})); });
  const lab=SVG('text',{x:padL-8,y:y+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); lab.textContent=label; svg.appendChild(lab);
}
function render(){
  const b=+bSl.value, acc=+accSl.value; bL.textContent='b(TL) = '+b.toFixed(2); accL.textContent='accuracy = '+acc.toFixed(2);
  listenBtn.classList.toggle('active',mode==='listen'); openBtn.classList.toggle('active',mode==='open');
  svg.innerHTML='';
  drawAxis(topY,'before');
  drawAxis(botY,'after');
  // current belief on the top axis
  const xb=xOf(b);
  svg.appendChild(SVG('circle',{cx:xb,cy:topY,r:7,fill:'var(--yellow)',stroke:'var(--bg)','stroke-width':2}));
  const cl=SVG('text',{x:xb,y:topY-12,'text-anchor':'middle','font-size':12,fill:'var(--yellow)','font-weight':600}); cl.textContent='b='+b.toFixed(2); svg.appendChild(cl);
  let txt;
  if(mode==='listen'){
    const bLft=bayes(b,acc,true), bRgt=bayes(b,acc,false);
    const pL = acc*b+(1-acc)*(1-b);   // P(hear-left | b)
    const pR = 1-pL;
    [[bLft,pL,'hear-left','var(--cyan)'],[bRgt,pR,'hear-right','var(--pink)']].forEach(([bn,p,name,col])=>{
      const xn=xOf(bn);
      drawArrow(svg,[xb,topY+8],[xn,botY-8],{color:col,markerId:'bmdp-'+name,width:2});
      svg.appendChild(SVG('circle',{cx:xn,cy:botY,r:7,fill:col,stroke:'var(--bg)','stroke-width':2}));
      const t=SVG('text',{x:xn,y:botY+22,'text-anchor':'middle','font-size':11,fill:col}); t.textContent=name+'  p='+p.toFixed(2); svg.appendChild(t);
      const t2=SVG('text',{x:xn,y:botY-12,'text-anchor':'middle','font-size':11,fill:col}); t2.textContent="b'="+bn.toFixed(2); svg.appendChild(t2);
    });
    txt='action = listen   (T = Id, so the belief moves only through the observation)\n'+
      'successor beliefs:  hear-left → '+bLft.toFixed(3)+'  with P='+pL.toFixed(3)+'      hear-right → '+bRgt.toFixed(3)+'  with P='+pR.toFixed(3)+'\n'+
      'reward ρ(b, listen) = -1 (a small listening cost), independent of which growl you hear.\n'+
      'this is a genuine stochastic transition in belief space — the Bellman equation V*(b)=max_a{ρ+γΣ_o P(o|b,a)V*(b^{a,o})} runs over a CONTINUUM of beliefs.';
  } else {
    const xn=xOf(0.5);
    drawArrow(svg,[xb,topY+8],[xn,botY-8],{color:'var(--green)',markerId:'bmdp-open',width:2});
    svg.appendChild(SVG('circle',{cx:xn,cy:botY,r:7,fill:'var(--green)',stroke:'var(--bg)','stroke-width':2}));
    const t=SVG('text',{x:xn,y:botY+22,'text-anchor':'middle','font-size':11,fill:'var(--green)'}); t.textContent='reset to 0.5'; svg.appendChild(t);
    txt='action = open a door   →   the episode ends; reward ρ(b, open) = Σ_s b(s)R(s, open) is the belief-weighted reward.\n'+
      'opening yields no informative observation, so the next episode restarts at the uninformative belief b = 0.5.\n'+
      'ρ(b, open-right) = b·R(TL,open-right) + (1-b)·R(TR,open-right)  — at b far from 0.5 one door is clearly worth the gamble.';
  }
  out.textContent=txt;
}
listenBtn.addEventListener('click',()=>{ mode='listen'; render(); });
openBtn.addEventListener('click',()=>{ mode='open'; render(); });
bSl.addEventListener('input',render);
accSl.addEventListener('input',render);
render();

const svg=$('#vfn-svg'), out=$('#vfn-out');
const bSl=$('#vfn-b'), bL=$('#vfn-b-lbl');
const tL=$('#vfn-tL'), tR=$('#vfn-tR'), tLis=$('#vfn-tLis');
const W=640,H=320, padL=58, padR=24, padT=24, padB=46;
// alpha = [alpha(TL), alpha(TR)]; value at b = alpha(TL)*b + alpha(TR)*(1-b)
const ALPHAS=[
  {name:'open-right', a:[10,-100], col:'var(--pink)', on:true},
  {name:'open-left',  a:[-100,10], col:'var(--cyan)', on:true},
  {name:'listen',     a:[1.5,1.5], col:'var(--violet)', on:true}
];
function val(al,b){ return al[0]*b + al[1]*(1-b); }
const yMin=-100, yMax=15;
function xOf(b){ return padL+(W-padL-padR)*b; }
function yOf(v){ return padT+(H-padT-padB)*(1-(v-yMin)/(yMax-yMin)); }
function render(){
  const b=+bSl.value; bL.textContent='b(TL) = '+b.toFixed(2);
  svg.innerHTML='';
  // axes
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:padL,y1:yOf(0),x2:W-padR,y2:yOf(0),stroke:'var(--line)','stroke-width':1}));
  [0,0.5,1].forEach(t=>{ const x=xOf(t); const tx=SVG('text',{x:x,y:H-padB+18,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); tx.textContent='b='+t; svg.appendChild(tx); });
  const yl=SVG('text',{x:padL-8,y:padT+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); yl.textContent='value'; svg.appendChild(yl);
  const xl=SVG('text',{x:W-padR,y:H-padB+18,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); xl.textContent='belief b(TL)'; svg.appendChild(xl);
  // each active alpha-vector as a line
  const active=ALPHAS.filter(A=>A.on);
  active.forEach((A,i)=>{
    svg.appendChild(SVG('line',{x1:xOf(0),y1:yOf(val(A.a,0)),x2:xOf(1),y2:yOf(val(A.a,1)),stroke:A.col,'stroke-width':1.6,'stroke-dasharray':'4 3'}));
    const lg=SVG('text',{x:W-padR,y:padT+14+i*15,'text-anchor':'end','font-size':11,fill:A.col}); lg.textContent='α['+A.name+'] = ('+A.a[0]+', '+A.a[1]+')'; svg.appendChild(lg);
  });
  // upper envelope V(b)=max over active alphas, sampled
  if(active.length){
    let path='';
    for(let i=0;i<=100;i++){ const bb=i/100; let best=-1e18, who=null; for(const A of active){ const v=val(A.a,bb); if(v>best){best=v;who=A;} } path+=(i?' L':'M')+xOf(bb)+' '+yOf(best); }
    svg.appendChild(SVG('path',{d:path,fill:'none',stroke:'var(--yellow)','stroke-width':3}));
    // marker at the queried belief
    let best=-1e18, who=null; for(const A of active){ const v=val(A.a,b); if(v>best){best=v;who=A;} }
    svg.appendChild(SVG('circle',{cx:xOf(b),cy:yOf(best),r:6,fill:'var(--yellow)',stroke:'var(--bg)','stroke-width':2}));
    out.textContent =
      'active α-vectors: '+active.map(A=>A.name).join(', ')+'\n'+
      'V(b) = max_α α·b   at b = '+b.toFixed(2)+'  →  '+best.toFixed(2)+'   (best plan here: '+who.name+')\n'+
      'the envelope is CONVEX and piecewise-linear; each kink is a belief where the optimal plan switches.\n'+
      'convexity = the value of information: V* peaks at the certain corners b=0,1 and sags in the uncertain middle.';
  } else {
    out.textContent='no α-vectors active — toggle some on. With none, there is no value function to draw.';
  }
}
tL.addEventListener('click',()=>{ const A=ALPHAS.find(x=>x.name==='open-left'); A.on=!A.on; tL.classList.toggle('active',A.on); render(); });
tR.addEventListener('click',()=>{ const A=ALPHAS.find(x=>x.name==='open-right'); A.on=!A.on; tR.classList.toggle('active',A.on); render(); });
tLis.addEventListener('click',()=>{ const A=ALPHAS.find(x=>x.name==='listen'); A.on=!A.on; tLis.classList.toggle('active',A.on); render(); });
tL.classList.add('active'); tR.classList.add('active'); tLis.classList.add('active');
bSl.addEventListener('input',render);
render();

const svg=$('#exact-svg'), out=$('#exact-out');
const gSl=$('#exact-gamma'), gL=$('#exact-gamma-lbl');
const gen=$('#exact-gen'), prune=$('#exact-prune'), reset=$('#exact-reset');
const W=640,H=320, padL=58, padR=24, padT=24, padB=46;
// belief coord b = b(TL); value at b = a[0]*b + a[1]*(1-b)
function val(a,b){ return a[0]*b + a[1]*(1-b); }
const yMin=-110, yMax=20;
function xOf(b){ return padL+(W-padL-padR)*b; }
function yOf(v){ return padT+(H-padT-padB)*(1-(v-yMin)/(yMax-yMin)); }
let cands=[], phase='empty';
function generate(){
  const g=+gSl.value;
  // A small but honest candidate set for the Tiger backup (illustrative α-vectors).
  // Survivors: open-right, open-left, and listen-then-decide. The rest are dominated everywhere.
  cands=[
    {name:'open-right',           a:[10,-100]},
    {name:'open-left',            a:[-100,10]},
    {name:'listen→decide',        a:[ 2*g+ -1, 2*g + -1]},   // flat, near the middle
    {name:'open-left if hear-R',  a:[-95,-40]},               // dominated cross-sum
    {name:'open-right if hear-L', a:[-40,-95]},               // dominated cross-sum
    {name:'always open-left(dom)',a:[-100,5]},                // dominated by open-left
    {name:'always open-right(dom)',a:[5,-100]}                // dominated by open-right
  ];
  phase='generated';
}
function dominatedEverywhere(A, others){
  // A is dominated if for some other vector B, B·b >= A·b for ALL b in [0,1] (sampled densely).
  for(const B of others){ if(B===A) continue; let dom=true; for(let i=0;i<=50;i++){ const b=i/50; if(val(B.a,b) < val(A.a,b) - 1e-9){ dom=false; break; } } if(dom) return true; }
  return false;
}
function doPrune(){
  if(phase==='empty') return;
  for(const A of cands){ A.pruned = dominatedEverywhere(A, cands); }
  phase='pruned';
}
function render(){
  const g=+gSl.value; gL.textContent='γ = '+g.toFixed(2);
  svg.innerHTML='';
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:padL,y1:yOf(0),x2:W-padR,y2:yOf(0),stroke:'var(--line)','stroke-width':1}));
  [0,0.5,1].forEach(t=>{ const tx=SVG('text',{x:xOf(t),y:H-padB+18,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); tx.textContent='b='+t; svg.appendChild(tx); });
  const xl=SVG('text',{x:W-padR,y:H-padB+18,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); xl.textContent='belief b(TL)'; svg.appendChild(xl);
  if(phase==='empty'){ out.textContent='press “one exact backup (generate)” to enumerate candidate α-vectors via the cross-sum over observations.'; return; }
  cands.forEach((A,i)=>{
    const faded = (phase==='pruned' && A.pruned);
    svg.appendChild(SVG('line',{x1:xOf(0),y1:yOf(val(A.a,0)),x2:xOf(1),y2:yOf(val(A.a,1)),stroke: faded?'var(--mute)':'var(--cyan)','stroke-width': faded?1:2,'stroke-dasharray': faded?'3 4':'0', opacity: faded?0.4:1}));
  });
  // survivors envelope
  const surv=cands.filter(A=> phase!=='pruned' || !A.pruned);
  let path='';
  for(let i=0;i<=100;i++){ const b=i/100; let best=-1e18; for(const A of surv){ best=Math.max(best,val(A.a,b)); } path+=(i?' L':'M')+xOf(b)+' '+yOf(best); }
  svg.appendChild(SVG('path',{d:path,fill:'none',stroke:'var(--yellow)','stroke-width':3}));
  const nDom = cands.filter(A=>A.pruned).length;
  out.textContent =
    'discount γ = '+g.toFixed(2)+'\n'+
    'candidates generated by the cross-sum: '+cands.length+'   '+(phase==='pruned'? ('→ pruned '+nDom+' dominated, '+(cands.length-nDom)+' survive') : '(now press “prune dominated”)')+'\n'+
    (phase==='pruned'
      ? 'survivors form the upper envelope (yellow); the faded dashed lines are α-vectors no belief ever selects — the LP found them infeasible-to-dominate.'
      : 'a backup can make up to |A|·|Γ|^|Ω| candidates — doubly exponential. Pruning (an LP feasibility check per vector) keeps only those that surface on the envelope.')+'\n'+
    'even after pruning, finite-horizon POMDP planning is PSPACE-complete.';
}
gen.addEventListener('click',()=>{ generate(); render(); });
prune.addEventListener('click',()=>{ doPrune(); render(); });
reset.addEventListener('click',()=>{ cands=[]; phase='empty'; render(); });
gSl.addEventListener('input',()=>{ if(phase!=='empty'){ generate(); } render(); });
render();

const svg=$('#pbvi-svg'), out=$('#pbvi-out');
const bSl=$('#pbvi-b'), bL=$('#pbvi-b-lbl');
const add=$('#pbvi-add'), reset=$('#pbvi-reset');
const W=640,H=320, padL=58, padR=24, padT=24, padB=46;
// TRUE PWLC V* of the Tiger problem (illustrative): upper envelope of these α-vectors.
const STAR=[ [10,-100], [-100,10], [3.5,3.5] ];
function val(a,b){ return a[0]*b + a[1]*(1-b); }
function vstar(b){ let m=-1e18; for(const a of STAR) m=Math.max(m,val(a,b)); return m; }
// The plan-library PBVI can pick from at any belief: pick the α maximizing α·b among these.
const LIB=[ [10,-100], [-100,10], [3.5,3.5], [-30,-30] ];
function bestAlphaAt(b){ let best=null,bv=-1e18; for(const a of LIB){ const v=val(a,b); if(v>bv){bv=v;best=a;} } return best; }
const yMin=-110, yMax=20;
function xOf(b){ return padL+(W-padL-padR)*b; }
function yOf(v){ return padT+(H-padT-padB)*(1-(v-yMin)/(yMax-yMin)); }
// a fixed schedule of reachable belief points to sample, in order
const SCHED=[0.5, 0.85, 0.15, 0.97, 0.03, 0.7, 0.3];
let B=[0.5], gamma=[];
function backup(){ // keep one α per belief point (dedup identical vectors)
  const set=[]; for(const b of B){ const a=bestAlphaAt(b); if(!set.some(x=>x[0]===a[0]&&x[1]===a[1])) set.push(a); } gamma=set;
}
function lb(b){ if(!gamma.length) return null; let m=-1e18; for(const a of gamma) m=Math.max(m,val(a,b)); return m; }
function render(){
  const b=+bSl.value; bL.textContent='b(TL) = '+b.toFixed(2);
  svg.innerHTML='';
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:padL,y1:yOf(0),x2:W-padR,y2:yOf(0),stroke:'var(--line)','stroke-width':1}));
  [0,0.5,1].forEach(t=>{ const tx=SVG('text',{x:xOf(t),y:H-padB+18,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); tx.textContent='b='+t; svg.appendChild(tx); });
  const xl=SVG('text',{x:W-padR,y:H-padB+18,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); xl.textContent='belief b(TL)'; svg.appendChild(xl);
  // true V* (faint)
  let sp=''; for(let i=0;i<=100;i++){ const bb=i/100; sp+=(i?' L':'M')+xOf(bb)+' '+yOf(vstar(bb)); }
  svg.appendChild(SVG('path',{d:sp,fill:'none',stroke:'var(--mute)','stroke-width':1.6,'stroke-dasharray':'5 4'}));
  const lgs=SVG('text',{x:W-padR,y:padT+14,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); lgs.textContent='true V* (PWLC)'; svg.appendChild(lgs);
  // lower-bound envelope
  if(gamma.length){
    let lp=''; for(let i=0;i<=100;i++){ const bb=i/100; lp+=(i?' L':'M')+xOf(bb)+' '+yOf(lb(bb)); }
    svg.appendChild(SVG('path',{d:lp,fill:'none',stroke:'var(--yellow)','stroke-width':3}));
    const lgy=SVG('text',{x:W-padR,y:padT+30,'text-anchor':'end','font-size':11,fill:'var(--yellow)'}); lgy.textContent='PBVI lower bound'; svg.appendChild(lgy);
  }
  // belief points
  for(const bp of B){ svg.appendChild(SVG('circle',{cx:xOf(bp),cy:yOf(0),r:4,fill:'var(--green)'})); }
  // query marker
  const lbq=lb(b), vsq=vstar(b);
  if(lbq!==null){ svg.appendChild(SVG('circle',{cx:xOf(b),cy:yOf(lbq),r:6,fill:'var(--yellow)',stroke:'var(--bg)','stroke-width':2})); }
  svg.appendChild(SVG('circle',{cx:xOf(b),cy:yOf(vsq),r:4,fill:'var(--mute)'}));
  out.textContent =
    'belief set B = { '+B.map(x=>x.toFixed(2)).join(', ')+' }   (|B| = '+B.length+',  α-vectors kept = '+gamma.length+')\n'+
    'at query b = '+b.toFixed(2)+':   PBVI lower bound = '+(lbq===null?'—':lbq.toFixed(2))+'     true V* = '+vsq.toFixed(2)+(lbq===null?'':('     gap = '+(vsq-lbq).toFixed(2)))+'\n'+
    'each backup keeps ONE α-vector per belief point, so |Γ| ≤ |B| — bounded, unlike exact VI.\n'+
    'the bound is a LOWER bound (every kept α is a realizable plan) and climbs toward V* as more reachable beliefs are sampled.';
}
add.addEventListener('click',()=>{ const next=SCHED[B.length % SCHED.length]; if(!B.some(x=>Math.abs(x-next)<1e-6)) B.push(next); backup(); render(); });
reset.addEventListener('click',()=>{ B=[0.5]; gamma=[]; render(); });
bSl.addEventListener('input',render);
backup(); render();
